DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS order_archive;
CREATE TABLE orders (order_id INTEGER PRIMARY KEY, customer TEXT, amount INTEGER);
CREATE TABLE order_archive (order_id INTEGER, customer TEXT, amount INTEGER);
INSERT INTO orders VALUES (1,'Asha',500),(2,'Bilal',750);
INSERT INTO order_archive (order_id,customer,amount) SELECT order_id,customer,amount FROM orders;
SELECT order_id,customer,amount FROM order_archive ORDER BY order_id;

DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS large_orders;
CREATE TABLE orders (order_id INTEGER PRIMARY KEY, customer TEXT, amount INTEGER);
CREATE TABLE large_orders (order_id INTEGER, customer TEXT, amount INTEGER);
INSERT INTO orders VALUES (1,'Asha',500),(2,'Bilal',750),(3,'Chitra',1200);
INSERT INTO large_orders SELECT order_id,customer,amount FROM orders WHERE amount>=700;
SELECT order_id,customer,amount FROM large_orders ORDER BY order_id;

DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS price_list;
CREATE TABLE products (product_id INTEGER PRIMARY KEY, product_name TEXT, price REAL);
CREATE TABLE price_list (product_name TEXT, price_with_tax REAL);
INSERT INTO products VALUES (1,'Keyboard',1000),(2,'Mouse',500);
INSERT INTO price_list (product_name,price_with_tax) SELECT product_name, ROUND(price*1.18,2) FROM products;
SELECT product_name,price_with_tax FROM price_list ORDER BY product_name;

DROP TABLE IF EXISTS sales;
DROP TABLE IF EXISTS sales_summary;
CREATE TABLE sales (sale_id INTEGER PRIMARY KEY, region TEXT, amount INTEGER);
CREATE TABLE sales_summary (region TEXT, total_amount INTEGER);
INSERT INTO sales VALUES (1,'East',300),(2,'West',400),(3,'East',200);
INSERT INTO sales_summary SELECT region,SUM(amount) FROM sales GROUP BY region;
SELECT region,total_amount FROM sales_summary ORDER BY region;

DROP TABLE IF EXISTS source_codes;
DROP TABLE IF EXISTS target_codes;
CREATE TABLE source_codes (code TEXT);
CREATE TABLE target_codes (code TEXT UNIQUE);
INSERT INTO source_codes VALUES ('A1'),('B2'),('A1');
INSERT INTO target_codes VALUES ('A1');
INSERT INTO target_codes (code) SELECT DISTINCT s.code FROM source_codes AS s WHERE NOT EXISTS (SELECT 1 FROM target_codes AS t WHERE t.code=s.code);
SELECT code FROM target_codes ORDER BY code;

